const snapshot = $json;
const overnightSummary = `${snapshot.overnightInbound ?? 0} inbound overnight (${snapshot.overnightCallbacksFired ?? 0} callbacks fired)`;
const todayQueue = `${snapshot.callsScheduledToday ?? 0} outbound calls in queue, ${snapshot.discoveryCallsToday ?? 0} discovery calls scheduled`;
const blockers = (snapshot.blockers ?? []).length === 0 ? 'No blockers.' : snapshot.blockers.join('; ');
const digest = `Postal Presort Daily Snapshot
Date: ${snapshot.date}

${overnightSummary}
${todayQueue}

Blockers: ${blockers}`;
return [{ json: { ...snapshot, digest } }];
